import { useState } from 'react';
import PaperCrumple, { type PaperCrumpleState, type PaperCrumpleRelease } from '../../../.upstream/src/ts-default/Micro/PaperCrumple/PaperCrumple';
import { DemoPanel } from '../../shared/demo-support';
import { microPaperArtwork } from '../../shared/micro-assets';
import styles from '../../shared/micro-demos.module.css';
import {componentClasses} from '../../shared/class-names';
const cn=(names:string)=>componentClasses(styles,names);

export default function PaperCrumpleDemo() {
  const [state, setState] = useState<PaperCrumpleState>('flat');
  const [release, setRelease] = useState<PaperCrumpleRelease>(/*__AW_STATE_state.release__*/);
  const [revision, setRevision] = useState(0);
  const [error, setError] = useState('');
  return <DemoPanel title="Paper Crumple · 纸张揉皱"><div className={cn("aw-micro-stack")}>
    <PaperCrumple src={microPaperArtwork}     releaseBehavior={release}   resetKey={revision}  onStateChange={setState} onError={reason => setError(reason.message)} /*__AW_PROPS_t0__*/  />
    <div className={cn("aw-micro-controls")}><label className={styles['aw-micro-label']}>松开后<select className={styles['aw-micro-select']} value={release} onChange={event => setRelease(event.target.value as PaperCrumpleRelease)}><option  /*__AW_PROPS_t2__*/ >保留折痕</option><option  /*__AW_PROPS_t3__*/ >恢复平整</option><option  /*__AW_PROPS_t4__*/ >保持揉皱</option></select></label><button className={styles['aw-micro-action']}  onClick={() => { setRevision(value => value + 1); setError(''); }} /*__AW_PROPS_t5__*/ >重置纸张</button></div>
    <p className={cn("aw-micro-status")} role="status" aria-live="polite">{error || `纸张状态：${state}。按住揉皱，拖动调整位置。`}</p>
  </div></DemoPanel>;
}
